import { useState, useEffect } from 'react';
import {
    regions,
    getProvincesByRegion,
    getCityMunByProvince,   // ← correct name
    getBarangayByMun        // ← correct name
} from 'philippine-location-json-for-geer';

// Active municipality servers — munCode → server URL
const MUNICIPALITY_SERVER_MAP = {
    'CAGAYAN DE ORO CITY (Capital)': { url: 'http://localhost:3001', code: '104305000' },
    'OPOL':                           { url: 'http://localhost:3002', code: '104321000' },
};

const PSGCSelector = ({ onChange, disabled = false, showBarangay = true }) => {
    const [regionCode,    setRegionCode]    = useState('');
    const [provinceCode,  setProvinceCode]  = useState('');
    const [munCode,       setMunCode]       = useState('');
    const [munName,       setMunName]       = useState('');
    const [barangay,      setBarangay]      = useState('');

    const [provinceList,  setProvinceList]  = useState([]);
    const [munList,       setMunList]       = useState([]);
    const [barangayList,  setBarangayList]  = useState([]);

    const isActiveMunicipality = !!MUNICIPALITY_SERVER_MAP[munName];

    useEffect(() => {
        const region   = regions.find(r => r.reg_code === regionCode);
        const province = provinceList.find(p => p.prov_code === provinceCode);
        // In the useEffect that calls onChange, change:
        // const mun    = munList.find(m => m.psgc_code === munCode);
        // const server = MUNICIPALITY_SERVER_MAP[mun?.name || ''];

        // TO — use munName state directly since it's already set:
        const server = MUNICIPALITY_SERVER_MAP[munName];

        onChange({
            regionCode,
            regionName:   region?.name   || '',
            provinceCode,
            provinceName: province?.name || '',
            munCityCode:  server?.code   || munCode,
            munCityName:  munName,
            barangayCode: barangay,
            barangayName: barangay,
            serverUrl:    server?.url    || null,
            isActive:     !!server,
            fullAddress:  [barangay, munName, province?.name, region?.name]
                .filter(Boolean).join(', ')
        });
    }, [regionCode, provinceCode, munCode, munName, barangay]); // eslint-disable-line react-hooks/exhaustive-deps

    const handleRegionChange = (e) => {
        const code = e.target.value;
        setRegionCode(code);
        setProvinceCode(''); setMunCode(''); setMunName(''); setBarangay('');
        setMunList([]); setBarangayList([]);
        setProvinceList(code ? getProvincesByRegion(code) : []);
    };

    const handleProvinceChange = (e) => {
        const code = e.target.value;

        setProvinceCode(code);
        setMunCode(''); setMunName(''); setBarangay('');
        setBarangayList([]);
        setMunList(code ? getCityMunByProvince(code) : []);
    };

    const handleMunChange = (e) => {
        const code = e.target.value;
        const mun = munList.find(m => m.psgc_code === code);
        setMunCode(code);
        setMunName(mun?.name || '');
        setBarangay('');
        setBarangayList(code ? getBarangayByMun(code) : []);
    };

    const selectStyle = {
        width: '100%', padding: '10px 12px',
        border: '1px solid #ddd', borderRadius: '4px',
        fontSize: '14px', boxSizing: 'border-box',
        marginBottom: '12px',
        backgroundColor: disabled ? '#f5f5f5' : 'white',
    };

    const labelStyle = {
        display: 'block', marginBottom: '6px',
        fontSize: '14px', fontWeight: '500'
    };

    return (
        <div>
            {/* Region */}
            <div>
                <label style={labelStyle}>Region</label>
                <select value={regionCode} disabled={disabled}
                    style={selectStyle} onChange={handleRegionChange}>
                    <option value="">-- Select Region --</option>
                    {regions.map(r => (
                        <option key={`reg-${r.reg_code}`} value={r.reg_code}>{r.name}</option>
                    ))}
                </select>
            </div>

            {/* Province */}
            <div>
                <label style={labelStyle}>Province</label>
                <select value={provinceCode} disabled={disabled || !regionCode}
                    style={selectStyle} onChange={handleProvinceChange}>
                    <option value="">-- Select Province --</option>
                    {provinceList.map(p => (
                        <option key={`prov-${p.prov_code}`} value={p.prov_code}>{p.name}</option>
                    ))}
                </select>
            </div>

            {/* Municipality */}
            <div>
                <label style={labelStyle}>Municipality / City</label>
                <select value={munCode} disabled={disabled || !provinceCode}
                    style={selectStyle} onChange={handleMunChange}>
                    <option value="">-- Select Municipality / City --</option>
                    {munList.map(m => (
                        <option key={`mun-${m.psgc_code}`} value={m.psgc_code}
                            style={{ fontWeight: MUNICIPALITY_SERVER_MAP[m.name] ? '600' : 'normal' }}>
                            {m.name}{MUNICIPALITY_SERVER_MAP[m.name] ? ' ✓' : ''}
                        </option>
                    ))}
                </select>
                {munCode && !isActiveMunicipality && (
                    <p style={{ color: '#999', fontSize: '12px', marginTop: -8, marginBottom: 8 }}>
                        This municipality has no active server in this system.
                    </p>
                )}
                {munCode && isActiveMunicipality && (
                    <p style={{ color: '#090', fontSize: '12px', marginTop: -8, marginBottom: 8 }}>
                        ✓ Active — {MUNICIPALITY_SERVER_MAP[munName].url}
                    </p>
                )}
            </div>

            {/* Barangay */}
            {showBarangay && (
                <div>
                    <label style={labelStyle}>Barangay</label>
                    <select value={barangay} disabled={disabled || !munCode}
                        style={selectStyle} onChange={e => setBarangay(e.target.value)}>
                        <option value="">-- Select Barangay --</option>
                        {barangayList.map(b => (
                            <option key={`brgy-${b.name}`} value={b.name}>{b.name}</option>
                        ))}
                    </select>
                </div>
            )}
        </div>
    );
};

export default PSGCSelector;