import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

// All known servers tried in order — first successful auth wins
const SERVERS = [
    'https://bantaylaot-production.up.railway.app', // central (central_admin, researcher)
    'http://localhost:3001',                         // Cagayan de Oro
    'http://localhost:3002',                         // Opol
];

const Login = () => {
    const [email,    setEmail]    = useState('');
    const [password, setPassword] = useState('');
    const [error,    setError]    = useState('');
    const [loading,  setLoading]  = useState(false);

    const navigate = useNavigate();

    const handleLogin = async (e) => {
        e.preventDefault();
        setError('');
        setLoading(true);

        for (const serverUrl of SERVERS) {
            try {
                const response = await fetch(`${serverUrl}/api/auth/login`, {
                    method:  'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body:    JSON.stringify({ email, password })
                });

                const data = await response.json();

                if (response.ok) {
                    if (data.role === 'fisher') {
                        setError('Fisher accounts cannot access the web dashboard.');
                        setLoading(false);
                        return;
                    }
                    localStorage.setItem('jwt_token',      data.token);
                    localStorage.setItem('userId',         data.userId);
                    localStorage.setItem('municipalityId', data.municipalityId);
                    localStorage.setItem('role',           data.role);
                    localStorage.setItem('adminName',      data.name || '');
                    localStorage.setItem('server_url',     serverUrl);
                    setLoading(false);
                    navigate('/home');
                    return;
                }

                // 401 = account found but wrong password — stop trying other servers
                if (response.status === 401) {
                    setError(data.message || 'Invalid email or password.');
                    setLoading(false);
                    return;
                }

                // 400 / 404 = account not found on this server — try the next one
            } catch {
                // server offline — try the next one
            }
        }

        setError('Account not found. Contact your administrator.');
        setLoading(false);
    };

    const inputStyle = {
        width: '100%', padding: '10px 12px',
        border: '1px solid #ddd', borderRadius: '4px',
        fontSize: '14px', boxSizing: 'border-box'
    };

    return (
        <div style={{
            display: 'flex', justifyContent: 'center',
            alignItems: 'center', minHeight: '100vh',
            backgroundColor: '#f0f2f5'
        }}>
            <div style={{
                background: 'white', padding: '40px',
                borderRadius: '8px', width: '400px',
                boxShadow: '0 2px 12px rgba(0,0,0,0.1)'
            }}>
                <h2 style={{ marginBottom: '4px' }}>BantayLaot</h2>
                <p style={{ color: '#666', marginBottom: '28px', fontSize: '14px' }}>
                    Admin Dashboard
                </p>

                {error && (
                    <div style={{
                        background: '#fff0f0', color: '#c00',
                        padding: '10px 14px', borderRadius: '4px',
                        marginBottom: '16px', fontSize: '14px'
                    }}>
                        {error}
                    </div>
                )}

                <form onSubmit={handleLogin}>
                    <div style={{ marginBottom: '16px' }}>
                        <label style={{ display: 'block', marginBottom: '6px', fontSize: '14px', fontWeight: '500' }}>
                            Email
                        </label>
                        <input
                            type="email" value={email}
                            onChange={e => setEmail(e.target.value)}
                            required style={inputStyle}
                            placeholder="Enter your email"
                            autoComplete="email"
                        />
                    </div>

                    <div style={{ marginBottom: '24px' }}>
                        <label style={{ display: 'block', marginBottom: '6px', fontSize: '14px', fontWeight: '500' }}>
                            Password
                        </label>
                        <input
                            type="password" value={password}
                            onChange={e => setPassword(e.target.value)}
                            required style={inputStyle}
                            placeholder="Enter your password"
                            autoComplete="current-password"
                        />
                    </div>

                    <button
                        type="submit"
                        disabled={loading}
                        style={{
                            width: '100%', padding: '12px',
                            background: loading ? '#999' : '#007AFF',
                            color: 'white', border: 'none',
                            borderRadius: '4px', fontSize: '15px',
                            cursor: loading ? 'not-allowed' : 'pointer'
                        }}
                    >
                        {loading ? 'Signing in...' : 'Sign In'}
                    </button>
                </form>
            </div>
        </div>
    );
};

export default Login;
