import React, { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

const AdminHeader = () => {
    const [open, setOpen] = useState(false);
    const dropdownRef     = useRef(null);
    const navigate        = useNavigate();
    const adminName       = localStorage.getItem('adminName') || 'Admin';
    const role            = localStorage.getItem('role') || '';

    useEffect(() => {
        const handler = (e) => {
            if (dropdownRef.current && !dropdownRef.current.contains(e.target)) {
                setOpen(false);
            }
        };
        document.addEventListener('mousedown', handler);
        return () => document.removeEventListener('mousedown', handler);
    }, []);

    const handleLogout = () => {
        localStorage.clear();
        navigate('/login');
    };

    return (
        <header style={{
            height: 52,
            background: '#0A1628',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            padding: '0 20px',
            flexShrink: 0,
            zIndex: 100
        }}>
            <span style={{ color: '#fff', fontWeight: 700, fontSize: 18, letterSpacing: 1 }}>
                BantayLaot
            </span>

            <div ref={dropdownRef} style={{ position: 'relative' }}>
                <button
                    onClick={() => setOpen(o => !o)}
                    style={{
                        background: '#1E3A5F',
                        border: 'none',
                        color: '#fff',
                        padding: '6px 14px',
                        borderRadius: 6,
                        cursor: 'pointer',
                        fontSize: 14,
                        display: 'flex',
                        alignItems: 'center',
                        gap: 8
                    }}
                >
                    <span style={{ fontSize: 18 }}>&#9632;</span>
                    {adminName}
                    <span style={{ fontSize: 10, opacity: 0.7 }}>&#9660;</span>
                </button>

                {open && (
                    <div style={{
                        position: 'absolute',
                        right: 0,
                        top: '110%',
                        background: '#fff',
                        border: '1px solid #e0e0e0',
                        borderRadius: 6,
                        minWidth: 160,
                        boxShadow: '0 4px 16px rgba(0,0,0,0.12)',
                        overflow: 'hidden',
                        zIndex: 200
                    }}>
                        {role !== 'researcher' && (
                            <>
                                <button
                                    onClick={() => { setOpen(false); navigate('/manage-users'); }}
                                    style={menuItemStyle}
                                >
                                    Manage Users
                                </button>
                                <hr style={{ margin: 0, borderColor: '#f0f0f0' }} />
                            </>
                        )}
                        <button
                            onClick={handleLogout}
                            style={{ ...menuItemStyle, color: '#c0392b' }}
                        >
                            Logout
                        </button>
                    </div>
                )}
            </div>
        </header>
    );
};

const menuItemStyle = {
    display: 'block',
    width: '100%',
    background: 'none',
    border: 'none',
    padding: '10px 16px',
    textAlign: 'left',
    cursor: 'pointer',
    fontSize: 14,
    color: '#1a1a1a'
};

export default AdminHeader;
