import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import Button from 'react-bootstrap/Button';
import Spinner from 'react-bootstrap/Spinner';
import { Chart } from 'react-google-charts';
import AdminHeader from '../components/AdminHeader';
import PSGCSelector from '../components/PSGCSelector';

const getServerUrl = () => localStorage.getItem('server_url') || 'http://localhost:3001';
const getRole      = () => localStorage.getItem('role') || '';

const MUNICIPALITIES = [
    { id: '104305000', name: 'Cagayan de Oro' },
    { id: '104321000', name: 'Opol'           },
];
const munName = (id) => MUNICIPALITIES.find(m => m.id === id)?.name || id || '—';

const STATUS_COLORS = { APPROVED: '#34C759', DECLINED: '#FF3B30', PENDING: '#FF9500', DEACTIVATED: '#8e8e93' };
const STATUS_BG     = { APPROVED: '#f0fff4', DECLINED: '#fff0f0', PENDING: '#fff8f0', DEACTIVATED: '#f5f5f5' };

const ROLE_STYLE = {
    fisher:          { color: '#005BAC', bg: '#e8f0fe', label: 'Fisher' },
    municipal_admin: { color: '#7B3F9E', bg: '#f3e8fd', label: 'Mun. Admin' },
    researcher:      { color: '#B25000', bg: '#fdf0e8', label: 'Researcher' },
};

// ── Small components ──────────────────────────────────────────────────────────
const StatusBadge = ({ status }) => (
    <span style={{
        display: 'inline-block', padding: '2px 10px', borderRadius: 20,
        fontSize: 11, fontWeight: 600, background: STATUS_BG[status] || '#f5f5f5',
        color: STATUS_COLORS[status] || '#555', border: `1px solid ${STATUS_COLORS[status] || '#ccc'}`
    }}>{status}</span>
);

const Th = ({ children, sortKey, sortBy, sortDir, onSort }) => {
    const active = sortBy === sortKey;
    return (
        <th onClick={() => onSort(sortKey)} style={{
            cursor: 'pointer', userSelect: 'none', whiteSpace: 'nowrap',
            padding: '8px 10px', background: '#f0f4f8', fontSize: 12, fontWeight: 600,
            color: active ? '#007AFF' : '#555', borderBottom: '1px solid #dde3ea'
        }}>
            {children}{active ? (sortDir === 'asc' ? ' ▲' : ' ▼') : ' ↕'}
        </th>
    );
};

// ── Main component ────────────────────────────────────────────────────────────
const ManageUsers = () => {
    const navigate = useNavigate();
    const role     = getRole();
    const isCentral = role === 'central_admin';

    const [allUsers,   setAllUsers]   = useState([]);
    const [loading,    setLoading]    = useState(false);

    // Filters
    const [search,       setSearch]       = useState('');
    const [statusFilter, setStatusFilter] = useState('ALL');
    const [munFilter,    setMunFilter]    = useState('ALL');
    const [roleFilter,   setRoleFilter]   = useState('ALL');

    // Sort
    const [sortBy,  setSortBy]  = useState('name');
    const [sortDir, setSortDir] = useState('asc');

    // Detail drawer
    const [selected, setSelected] = useState(null);

    // Action feedback
    const [actionLoading,  setActionLoading]  = useState({});
    const [actionFeedback, setActionFeedback] = useState({});

    // Researcher form
    const [showResearcher, setShowResearcher] = useState(false);
    const [rName,  setRName]  = useState('');
    const [rEmail, setREmail] = useState('');
    const [rPass,  setRPass]  = useState('');
    const [rLoading, setRLoading] = useState(false);
    const [rMsg,   setRMsg]   = useState(null);

    // Municipal admin form
    const [showMunAdmin, setShowMunAdmin] = useState(false);
    const [mName,    setMName]    = useState('');
    const [mEmail,   setMEmail]   = useState('');
    const [mPass,    setMPass]    = useState('');
    const [mPsgc,    setMPsgc]    = useState({});
    const [mLoading, setMLoading] = useState(false);
    const [mMsg,     setMMsg]     = useState(null);

    // Add fisher form (municipal admin only)
    const [showAddFisher,    setShowAddFisher]    = useState(false);
    const [fName,            setFName]            = useState('');
    const [fEmail,           setFEmail]           = useState('');
    const [fPass,            setFPass]            = useState('');
    const [fBirthdate,       setFBirthdate]       = useState('');
    const [fBarangay,        setFBarangay]        = useState('');
    const [fBoatName,        setFBoatName]        = useState('');
    const [fBoatType,        setFBoatType]        = useState('Motorized');
    const [fLength,          setFLength]          = useState('');
    const [fEnginePower,     setFEnginePower]     = useState('');
    const [fRegNumber,       setFRegNumber]       = useState('');
    const [fLoading,         setFLoading]         = useState(false);
    const [fMsg,             setFMsg]             = useState(null);
    const [fBarangayList,    setFBarangayList]    = useState([]);

    const createResearcher = async (e) => {
        e.preventDefault();
        setRLoading(true); setRMsg(null);
        try {
            const res = await fetch(`${getServerUrl()}/api/auth/researcher-setup`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ name: rName, email: rEmail, password: rPass })
            });
            const data = await res.json();
            if (res.ok) {
                setRMsg({ type: 'success', text: `Researcher account created for ${rEmail}.` });
                setRName(''); setREmail(''); setRPass('');
                fetchUsers();
            } else {
                setRMsg({ type: 'error', text: data.message || 'Failed.' });
            }
        } catch { setRMsg({ type: 'error', text: 'Cannot connect to server.' }); }
        finally { setRLoading(false); }
    };

    const createMunAdmin = async (e) => {
        e.preventDefault();
        setMMsg(null);
        if (!mPsgc.munCityCode) {
            setMMsg({ type: 'error', text: 'Please select a municipality.' });
            return;
        }
        if (!mPsgc.isActive) {
            setMMsg({ type: 'error', text: `No active server for ${mPsgc.munCityName}. Start the server first.` });
            return;
        }
        setMLoading(true);
        try {
            const res = await fetch(`${mPsgc.serverUrl}/api/auth/admin-setup`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    name:           mName,
                    email:          mEmail,
                    password:       mPass,
                    role:           'municipal_admin',
                    municipalityId: mPsgc.munCityCode,
                    regionCode:     mPsgc.regionCode   || '',
                    regionName:     mPsgc.regionName   || '',
                    provinceCode:   mPsgc.provinceCode || '',
                    provinceName:   mPsgc.provinceName || '',
                    munCityCode:    mPsgc.munCityCode  || '',
                    munCityName:    mPsgc.munCityName  || '',
                    barangayCode:   '',
                    barangayName:   '',
                })
            });
            const data = await res.json();
            if (res.ok) {
                setMMsg({ type: 'success', text: `Municipal admin created for ${mEmail} (${mPsgc.munCityName}).` });
                setMName(''); setMEmail(''); setMPass(''); setMPsgc({});
                fetchUsers();
            } else {
                setMMsg({ type: 'error', text: data.message || 'Failed.' });
            }
        } catch { setMMsg({ type: 'error', text: 'Cannot connect to the municipal server.' }); }
        finally { setMLoading(false); }
    };

    // Load barangay list for the Add Fisher form (municipal admin only, runs once)
    useEffect(() => {
        if (isCentral) return;
        import('philippine-location-json-for-geer').then(({ getBarangayByMun }) => {
            const serverUrl = getServerUrl();
            const MUN_CODE = { 'http://localhost:3001': '104305', 'http://localhost:3002': '104321' };
            const code = MUN_CODE[serverUrl] || '';
            if (code) setFBarangayList(getBarangayByMun(code).map(b => b.name).sort());
        }).catch(() => {});
    }, []); // eslint-disable-line react-hooks/exhaustive-deps

    const createFisher = async (e) => {
        e.preventDefault();
        setFLoading(true); setFMsg(null);
        const token = localStorage.getItem('jwt_token');
        try {
            const res = await fetch(`${getServerUrl()}/api/auth/fisher-setup`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
                body: JSON.stringify({
                    name:     fName,
                    email:    fEmail,
                    password: fPass,
                    birthdate: fBirthdate,
                    barangayName: fBarangay,
                    boatName:  fBoatName,
                    boatType:  fBoatType,
                    length:    fLength ? parseFloat(fLength) : 0,
                    enginePower:        fEnginePower,
                    registrationNumber: fRegNumber,
                })
            });
            const data = await res.json();
            if (res.ok) {
                setFMsg({ type: 'success', text: `Fisher account created for ${fEmail}.` });
                setFName(''); setFEmail(''); setFPass(''); setFBirthdate(''); setFBarangay('');
                setFBoatName(''); setFBoatType('Motorized'); setFLength(''); setFEnginePower(''); setFRegNumber('');
                fetchUsers();
            } else {
                setFMsg({ type: 'error', text: data.message || 'Failed.' });
            }
        } catch { setFMsg({ type: 'error', text: 'Cannot connect to server.' }); }
        finally { setFLoading(false); }
    };

    const fetchUsers = useCallback(async () => {
        const token = localStorage.getItem('jwt_token');
        setLoading(true);
        try {
            const usersRes = await fetch(`${getServerUrl()}/api/users`, { headers: { Authorization: `Bearer ${token}` } });
            const users = await usersRes.json();
            let allData = Array.isArray(users) ? users : [];

            if (getRole() === 'central_admin') {
                const rRes = await fetch(`${getServerUrl()}/api/researchers`, { headers: { Authorization: `Bearer ${token}` } });
                if (rRes.ok) {
                    const researchers = await rRes.json();
                    const tagged = (Array.isArray(researchers) ? researchers : []).map(r => ({ ...r, _isResearcher: true }));
                    allData = [...allData, ...tagged];
                }
            }

            setAllUsers(allData);
        } catch (e) {
            console.error(e);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => { fetchUsers(); }, [fetchUsers]);

    const handleStatusChange = useCallback(async (userId, newStatus) => {
        const token = localStorage.getItem('jwt_token');
        const user  = allUsers.find(u => u._id === userId);
        const url   = user?._isResearcher
            ? `${getServerUrl()}/api/researchers/${userId}/status`
            : `${getServerUrl()}/api/users/${userId}/status`;
        setActionLoading(p => ({ ...p, [userId]: true }));
        try {
            const res = await fetch(url, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
                body: JSON.stringify({ status: newStatus })
            });
            if (!res.ok) throw new Error();
            setAllUsers(p => p.map(u => u._id === userId ? { ...u, status: newStatus } : u));
            if (selected?._id === userId) setSelected(p => ({ ...p, status: newStatus }));
            setActionFeedback(p => ({ ...p, [userId]: newStatus === 'APPROVED' ? 'approved' : 'declined' }));
        } catch {
            setActionFeedback(p => ({ ...p, [userId]: 'error' }));
        } finally {
            setActionLoading(p => ({ ...p, [userId]: false }));
        }
    }, [selected, allUsers]);

    const handleSort = (key) => {
        if (sortBy === key) setSortDir(d => d === 'asc' ? 'desc' : 'asc');
        else { setSortBy(key); setSortDir('asc'); }
    };

    // ── Derived data ──────────────────────────────────────────────────────────
    const filtered = useMemo(() => {
        const q = search.toLowerCase();
        return allUsers.filter(u => {
            if (statusFilter !== 'ALL' && u.status !== statusFilter) return false;
            if (munFilter !== 'ALL' && u.municipalityId !== munFilter) return false;
            if (roleFilter !== 'ALL' && u.role !== roleFilter) return false;
            if (q && !u.name?.toLowerCase().includes(q) && !u.email?.toLowerCase().includes(q) && !u.barangayName?.toLowerCase().includes(q)) return false;
            return true;
        });
    }, [allUsers, statusFilter, munFilter, roleFilter, search]);

    const sorted = useMemo(() => {
        return [...filtered].sort((a, b) => {
            let av = a[sortBy] ?? ''; let bv = b[sortBy] ?? '';
            if (sortBy === 'createdAt') { av = new Date(av); bv = new Date(bv); }
            else { av = String(av).toLowerCase(); bv = String(bv).toLowerCase(); }
            if (av < bv) return sortDir === 'asc' ? -1 : 1;
            if (av > bv) return sortDir === 'asc' ? 1 : -1;
            return 0;
        });
    }, [filtered, sortBy, sortDir]);

    // Chart data — by municipality or barangay
    const chartData = useMemo(() => {
        const fishers = allUsers.filter(u => u.role === 'fisher');
        if (isCentral && munFilter === 'ALL') {
            const counts = {};
            fishers.forEach(u => { const n = munName(u.municipalityId); counts[n] = (counts[n] || 0) + 1; });
            return [['Municipality', 'Fishers'], ...Object.entries(counts).sort((a, b) => b[1] - a[1])];
        } else {
            const counts = {};
            (munFilter !== 'ALL' ? fishers.filter(u => u.municipalityId === munFilter) : fishers).forEach(u => {
                const b = u.barangayName || 'Unknown'; counts[b] = (counts[b] || 0) + 1;
            });
            return [['Barangay', 'Fishers'], ...Object.entries(counts).sort((a, b) => b[1] - a[1])];
        }
    }, [allUsers, munFilter, isCentral]);

    const counts = useMemo(() => ({
        ALL:         allUsers.length,
        PENDING:     allUsers.filter(u => u.status === 'PENDING').length,
        APPROVED:    allUsers.filter(u => u.status === 'APPROVED').length,
        DECLINED:    allUsers.filter(u => u.status === 'DECLINED').length,
        DEACTIVATED: allUsers.filter(u => u.status === 'DEACTIVATED').length,
    }), [allUsers]);

    // ── Render ────────────────────────────────────────────────────────────────
    return (
        <div style={{ display: 'flex', flexDirection: 'column', height: '100vh', background: '#f5f7fa' }}>
            <AdminHeader />

            <div style={{ padding: '20px 24px', flex: 1, overflowY: 'auto' }}>

                {/* Header */}
                <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 16 }}>
                    <button onClick={() => navigate(-1)}
                        style={{ background: 'none', border: 'none', cursor: 'pointer', fontSize: 20, color: '#555' }}>
                        &#8592;
                    </button>
                    <h4 style={{ margin: 0, flex: 1 }}>Manage Users</h4>
                    <button onClick={fetchUsers} disabled={loading}
                        style={{ background: '#f0f4f8', border: '1px solid #dde3ea', borderRadius: 6, padding: '6px 12px', cursor: 'pointer', fontSize: 13 }}>
                        {loading ? <Spinner animation="border" size="sm" /> : '↻ Refresh'}
                    </button>
                </div>

                {/* Researcher account section (central admin only) */}
                {isCentral && (
                    <div style={{ marginBottom: 16, border: '1px solid #d0e4f7', borderRadius: 8, overflow: 'hidden' }}>
                        <button onClick={() => { setShowResearcher(v => !v); setRMsg(null); }}
                            style={{ width: '100%', padding: '10px 16px', background: '#f0f7ff', border: 'none', textAlign: 'left', cursor: 'pointer', fontWeight: 600, fontSize: 13, color: '#005BAC', display: 'flex', justifyContent: 'space-between' }}>
                            <span>+ Create Researcher Account</span>
                            <span>{showResearcher ? '▲' : '▼'}</span>
                        </button>
                        {showResearcher && (
                            <div style={{ padding: 16, background: '#fff' }}>
                                <p style={{ fontSize: 12, color: '#666', marginBottom: 10 }}>
                                    Researcher accounts have read-only access to anonymized data and can download CSVs and images.
                                </p>
                                {rMsg && (
                                    <div style={{ padding: '6px 10px', borderRadius: 4, marginBottom: 10, fontSize: 12,
                                        background: rMsg.type === 'success' ? '#f0fff4' : '#fff0f0',
                                        color: rMsg.type === 'success' ? '#276749' : '#c00' }}>
                                        {rMsg.text}
                                    </div>
                                )}
                                <form onSubmit={createResearcher} style={{ display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'flex-end' }}>
                                    <input type="text" placeholder="Full name" required value={rName} onChange={e => setRName(e.target.value)} className="form-control form-control-sm" style={{ flex: '1 1 140px' }} />
                                    <input type="email" placeholder="Email" required value={rEmail} onChange={e => setREmail(e.target.value)} className="form-control form-control-sm" style={{ flex: '1 1 160px' }} />
                                    <input type="password" placeholder="Password" required minLength={6} value={rPass} onChange={e => setRPass(e.target.value)} className="form-control form-control-sm" style={{ flex: '1 1 120px' }} />
                                    <Button type="submit" size="sm" variant="primary" disabled={rLoading}>
                                        {rLoading ? <Spinner animation="border" size="sm" /> : 'Create'}
                                    </Button>
                                </form>
                            </div>
                        )}
                    </div>
                )}

                {/* Municipal admin creation section (central admin only) */}
                {isCentral && (
                    <div style={{ marginBottom: 16, border: '1px solid #e0d0f7', borderRadius: 8, overflow: 'hidden' }}>
                        <button onClick={() => { setShowMunAdmin(v => !v); setMMsg(null); }}
                            style={{ width: '100%', padding: '10px 16px', background: '#f8f0ff', border: 'none', textAlign: 'left', cursor: 'pointer', fontWeight: 600, fontSize: 13, color: '#7B3F9E', display: 'flex', justifyContent: 'space-between' }}>
                            <span>+ Create Municipal Admin Account</span>
                            <span>{showMunAdmin ? '▲' : '▼'}</span>
                        </button>
                        {showMunAdmin && (
                            <div style={{ padding: 16, background: '#fff' }}>
                                <p style={{ fontSize: 12, color: '#666', marginBottom: 10 }}>
                                    Municipal admin accounts are created directly on the selected municipality's server. The server must be running.
                                </p>
                                {mMsg && (
                                    <div style={{ padding: '6px 10px', borderRadius: 4, marginBottom: 10, fontSize: 12,
                                        background: mMsg.type === 'success' ? '#f0fff4' : '#fff0f0',
                                        color: mMsg.type === 'success' ? '#276749' : '#c00' }}>
                                        {mMsg.text}
                                    </div>
                                )}
                                <form onSubmit={createMunAdmin}>
                                    <div style={{ marginBottom: 10 }}>
                                        <label style={{ fontSize: 12, fontWeight: 600, display: 'block', marginBottom: 4 }}>Municipality</label>
                                        <PSGCSelector onChange={setMPsgc} showBarangay={false} />
                                        {mPsgc.munCityName && !mPsgc.isActive && (
                                            <p style={{ color: '#c00', fontSize: 12, margin: '4px 0 0' }}>⚠ No active server for {mPsgc.munCityName}.</p>
                                        )}
                                        {mPsgc.isActive && (
                                            <p style={{ color: '#090', fontSize: 12, margin: '4px 0 0' }}>✓ Connected to: {mPsgc.serverUrl}</p>
                                        )}
                                    </div>
                                    <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'flex-end' }}>
                                        <input type="text" placeholder="Full name" required value={mName} onChange={e => setMName(e.target.value)} className="form-control form-control-sm" style={{ flex: '1 1 140px' }} />
                                        <input type="email" placeholder="Email" required value={mEmail} onChange={e => setMEmail(e.target.value)} className="form-control form-control-sm" style={{ flex: '1 1 160px' }} />
                                        <input type="password" placeholder="Password (8+ chars)" required minLength={8} value={mPass} onChange={e => setMPass(e.target.value)} className="form-control form-control-sm" style={{ flex: '1 1 140px' }} />
                                        <Button type="submit" size="sm" style={{ background: '#7B3F9E', border: 'none' }} disabled={mLoading}>
                                            {mLoading ? <Spinner animation="border" size="sm" /> : 'Create'}
                                        </Button>
                                    </div>
                                </form>
                            </div>
                        )}
                    </div>
                )}

                {/* Add Fisher section (municipal admin only) */}
                {!isCentral && (
                    <div style={{ marginBottom: 16, border: '1px solid #c6e8c8', borderRadius: 8, overflow: 'hidden' }}>
                        <button onClick={() => { setShowAddFisher(v => !v); setFMsg(null); }}
                            style={{ width: '100%', padding: '10px 16px', background: '#f0fff4', border: 'none', textAlign: 'left', cursor: 'pointer', fontWeight: 600, fontSize: 13, color: '#1a6b2d', display: 'flex', justifyContent: 'space-between' }}>
                            <span>+ Add Fisher Account</span>
                            <span>{showAddFisher ? '▲' : '▼'}</span>
                        </button>
                        {showAddFisher && (
                            <div style={{ padding: 16, background: '#fff' }}>
                                <p style={{ fontSize: 12, color: '#666', marginBottom: 10 }}>
                                    Creates a fisher account directly as Approved. All fields marked * are required.
                                </p>
                                {fMsg && (
                                    <div style={{ padding: '6px 10px', borderRadius: 4, marginBottom: 10, fontSize: 12,
                                        background: fMsg.type === 'success' ? '#f0fff4' : '#fff0f0',
                                        color: fMsg.type === 'success' ? '#276749' : '#c00' }}>
                                        {fMsg.text}
                                    </div>
                                )}
                                <form onSubmit={createFisher}>
                                    <p style={{ fontSize: 12, fontWeight: 600, color: '#333', margin: '0 0 6px' }}>Account Details</p>
                                    <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 10 }}>
                                        <input type="text" placeholder="Full name *" required value={fName} onChange={e => setFName(e.target.value)} className="form-control form-control-sm" style={{ flex: '1 1 160px' }} />
                                        <input type="email" placeholder="Email *" required value={fEmail} onChange={e => setFEmail(e.target.value)} className="form-control form-control-sm" style={{ flex: '1 1 160px' }} />
                                        <input type="password" placeholder="Password * (6+ chars)" required minLength={6} value={fPass} onChange={e => setFPass(e.target.value)} className="form-control form-control-sm" style={{ flex: '1 1 140px' }} />
                                        <input type="text" placeholder="Birthdate (optional)" value={fBirthdate} onChange={e => setFBirthdate(e.target.value)} className="form-control form-control-sm" style={{ flex: '1 1 140px' }} />
                                        {fBarangayList.length > 0 ? (
                                            <select value={fBarangay} onChange={e => setFBarangay(e.target.value)} className="form-select form-select-sm" style={{ flex: '1 1 160px' }}>
                                                <option value="">-- Barangay (optional) --</option>
                                                {fBarangayList.map(b => <option key={b} value={b}>{b}</option>)}
                                            </select>
                                        ) : (
                                            <input type="text" placeholder="Barangay (optional)" value={fBarangay} onChange={e => setFBarangay(e.target.value)} className="form-control form-control-sm" style={{ flex: '1 1 160px' }} />
                                        )}
                                    </div>
                                    <p style={{ fontSize: 12, fontWeight: 600, color: '#333', margin: '0 0 6px' }}>Boat Details</p>
                                    <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 10 }}>
                                        <input type="text" placeholder="Boat name *" required value={fBoatName} onChange={e => setFBoatName(e.target.value)} className="form-control form-control-sm" style={{ flex: '1 1 140px' }} />
                                        <select value={fBoatType} onChange={e => setFBoatType(e.target.value)} className="form-select form-select-sm" style={{ flex: '0 0 140px' }}>
                                            <option value="Motorized">Motorized</option>
                                            <option value="Non-Motorized">Non-Motorized</option>
                                            <option value="Sail">Sail</option>
                                        </select>
                                        <input type="number" placeholder="Length (m)" value={fLength} onChange={e => setFLength(e.target.value)} className="form-control form-control-sm" style={{ flex: '0 0 100px' }} min="0" step="0.1" />
                                        <input type="text" placeholder="Engine power" value={fEnginePower} onChange={e => setFEnginePower(e.target.value)} className="form-control form-control-sm" style={{ flex: '1 1 120px' }} />
                                        <input type="text" placeholder="Reg. number" value={fRegNumber} onChange={e => setFRegNumber(e.target.value)} className="form-control form-control-sm" style={{ flex: '1 1 120px' }} />
                                    </div>
                                    <Button type="submit" size="sm" variant="success" disabled={fLoading}>
                                        {fLoading ? <Spinner animation="border" size="sm" /> : 'Create Fisher'}
                                    </Button>
                                </form>
                            </div>
                        )}
                    </div>
                )}

                {/* Stats row */}
                <div style={{ display: 'flex', gap: 10, marginBottom: 16, flexWrap: 'wrap' }}>
                    {[
                        { label: 'Total',       key: 'ALL',         color: '#007AFF' },
                        { label: 'Pending',     key: 'PENDING',     color: '#FF9500' },
                        { label: 'Approved',    key: 'APPROVED',    color: '#34C759' },
                        { label: 'Declined',    key: 'DECLINED',    color: '#FF3B30' },
                        { label: 'Deactivated', key: 'DEACTIVATED', color: '#8e8e93' },
                    ].map(({ label, key, color }) => (
                        <div key={key}
                            onClick={() => setStatusFilter(statusFilter === key ? 'ALL' : key)}
                            style={{ flex: '1 1 100px', background: '#fff', border: `2px solid ${statusFilter === key ? color : '#e0e0e0'}`,
                                borderRadius: 8, padding: '10px 14px', cursor: 'pointer', textAlign: 'center' }}>
                            <div style={{ fontSize: 22, fontWeight: 700, color }}>{counts[key]}</div>
                            <div style={{ fontSize: 11, color: '#888' }}>{label}</div>
                        </div>
                    ))}
                </div>

                <div style={{ display: 'flex', gap: 16, alignItems: 'flex-start' }}>

                    {/* Left: table + filters */}
                    <div style={{ flex: 1, minWidth: 0 }}>

                        {/* Filters row */}
                        <div style={{ display: 'flex', gap: 8, marginBottom: 10, flexWrap: 'wrap' }}>
                            <input
                                type="text" placeholder="🔍 Search name, email, barangay…"
                                value={search} onChange={e => setSearch(e.target.value)}
                                className="form-control form-control-sm"
                                style={{ flex: '1 1 200px' }}
                            />
                            {isCentral && (
                                <select value={munFilter} onChange={e => setMunFilter(e.target.value)} className="form-select form-select-sm" style={{ flex: '0 0 140px' }}>
                                    <option value="ALL">All Municipalities</option>
                                    {MUNICIPALITIES.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
                                </select>
                            )}
                            <select value={roleFilter} onChange={e => setRoleFilter(e.target.value)} className="form-select form-select-sm" style={{ flex: '0 0 130px' }}>
                                <option value="ALL">All Roles</option>
                                <option value="fisher">Fisher</option>
                                <option value="municipal_admin">Municipal Admin</option>
                                {isCentral && <option value="researcher">Researcher</option>}
                            </select>
                            <select value={statusFilter} onChange={e => setStatusFilter(e.target.value)} className="form-select form-select-sm" style={{ flex: '0 0 130px' }}>
                                <option value="ALL">All Statuses</option>
                                <option value="PENDING">Pending</option>
                                <option value="APPROVED">Approved</option>
                                <option value="DECLINED">Declined</option>
                                <option value="DEACTIVATED">Deactivated</option>
                            </select>
                        </div>

                        {/* Result count */}
                        <div style={{ fontSize: 12, color: '#888', marginBottom: 6 }}>
                            {sorted.length} result{sorted.length !== 1 ? 's' : ''}
                        </div>

                        {/* Table */}
                        {loading && allUsers.length === 0 ? (
                            <div className="text-center py-5"><Spinner animation="border" /><p className="mt-2 text-muted">Loading users…</p></div>
                        ) : (
                            <div style={{ overflowX: 'auto', borderRadius: 8, border: '1px solid #dde3ea', background: '#fff' }}>
                                <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 13 }}>
                                    <thead>
                                        <tr>
                                            <Th sortKey="name"          sortBy={sortBy} sortDir={sortDir} onSort={handleSort}>Name</Th>
                                            <Th sortKey="email"         sortBy={sortBy} sortDir={sortDir} onSort={handleSort}>Email</Th>
                                            {isCentral && <Th sortKey="municipalityId" sortBy={sortBy} sortDir={sortDir} onSort={handleSort}>Municipality</Th>}
                                            <Th sortKey="barangayName"  sortBy={sortBy} sortDir={sortDir} onSort={handleSort}>Barangay</Th>
                                            <Th sortKey="role"          sortBy={sortBy} sortDir={sortDir} onSort={handleSort}>Role</Th>
                                            <Th sortKey="status"        sortBy={sortBy} sortDir={sortDir} onSort={handleSort}>Status</Th>
                                            <Th sortKey="createdAt"     sortBy={sortBy} sortDir={sortDir} onSort={handleSort}>Registered</Th>
                                            {!isCentral && <th style={{ padding: '8px 10px', background: '#f0f4f8', fontSize: 12, fontWeight: 600, color: '#555', borderBottom: '1px solid #dde3ea' }}>Actions</th>}
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {sorted.length === 0 ? (
                                            <tr><td colSpan={isCentral ? 7 : 8} style={{ textAlign: 'center', padding: 32, color: '#aaa', fontSize: 13 }}>No users match the current filters.</td></tr>
                                        ) : sorted.map((u, i) => (
                                            <tr key={u._id}
                                                onClick={() => setSelected(selected?._id === u._id ? null : u)}
                                                style={{ background: selected?._id === u._id ? '#f0f7ff' : i % 2 === 0 ? '#fff' : '#fafbfc', cursor: 'pointer', borderBottom: '1px solid #f0f0f0' }}>
                                                <td style={{ padding: '8px 10px', fontWeight: 500 }}>{u.name}</td>
                                                <td style={{ padding: '8px 10px', color: '#555' }}>{u.email}</td>
                                                {isCentral && <td style={{ padding: '8px 10px' }}>{munName(u.municipalityId)}</td>}
                                                <td style={{ padding: '8px 10px', color: '#555' }}>{u.barangayName || '—'}</td>
                                                <td style={{ padding: '8px 10px' }}>
                                                    {(() => {
                                                        const rs = ROLE_STYLE[u.role] || { color: '#555', bg: '#eee', label: u.role };
                                                        return (
                                                            <span style={{ fontSize: 11, color: rs.color, background: rs.bg, padding: '2px 8px', borderRadius: 20 }}>
                                                                {rs.label}
                                                            </span>
                                                        );
                                                    })()}
                                                </td>
                                                <td style={{ padding: '8px 10px' }}><StatusBadge status={u.status} /></td>
                                                <td style={{ padding: '8px 10px', color: '#888', whiteSpace: 'nowrap' }}>
                                                    {u.createdAt ? new Date(u.createdAt).toLocaleDateString('en-PH', { year: 'numeric', month: 'short', day: 'numeric' }) : '—'}
                                                </td>
                                                {!isCentral && (
                                                    <td style={{ padding: '8px 10px' }} onClick={e => e.stopPropagation()}>
                                                        {u.role === 'fisher' ? (
                                                            <div style={{ display: 'flex', gap: 4 }}>
                                                                <button
                                                                    disabled={u.status === 'APPROVED' || actionLoading[u._id]}
                                                                    onClick={() => handleStatusChange(u._id, 'APPROVED')}
                                                                    title="Approve"
                                                                    style={{ fontSize: 11, padding: '3px 8px', background: u.status === 'APPROVED' ? '#e0e0e0' : '#34C759', color: '#fff', border: 'none', borderRadius: 4, cursor: u.status === 'APPROVED' ? 'default' : 'pointer' }}>
                                                                    {actionLoading[u._id] ? '…' : '✔'}
                                                                </button>
                                                                <button
                                                                    disabled={u.status === 'DECLINED' || actionLoading[u._id]}
                                                                    onClick={() => handleStatusChange(u._id, 'DECLINED')}
                                                                    title="Decline"
                                                                    style={{ fontSize: 11, padding: '3px 8px', border: 'none', borderRadius: 4,
                                                                        background: u.status === 'DECLINED' ? '#e0e0e0' : '#FF3B30',
                                                                        color: u.status === 'DECLINED' ? '#aaa' : '#fff',
                                                                        cursor: u.status === 'DECLINED' ? 'default' : 'pointer' }}>
                                                                    {actionLoading[u._id] ? '…' : '✖'}
                                                                </button>
                                                                <button
                                                                    disabled={u.status === 'DEACTIVATED' || actionLoading[u._id]}
                                                                    onClick={() => handleStatusChange(u._id, 'DEACTIVATED')}
                                                                    title="Deactivate"
                                                                    style={{ fontSize: 11, padding: '3px 8px', background: u.status === 'DEACTIVATED' ? '#e0e0e0' : '#8e8e93', color: '#fff', border: 'none', borderRadius: 4, cursor: u.status === 'DEACTIVATED' ? 'default' : 'pointer' }}>
                                                                    {actionLoading[u._id] ? '…' : '⊘'}
                                                                </button>
                                                            </div>
                                                        ) : (
                                                            <span style={{ color: '#aaa', fontSize: 11 }}>—</span>
                                                        )}
                                                    </td>
                                                )}
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        )}
                    </div>

                    {/* Right: detail + chart */}
                    <div style={{ width: 280, flexShrink: 0 }}>

                        {/* User detail card */}
                        {selected ? (
                            <div style={{ background: '#fff', borderRadius: 8, border: '1px solid #dde3ea', padding: 16, marginBottom: 14, fontSize: 13 }}>
                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 10 }}>
                                    <div>
                                        <div style={{ fontWeight: 700, fontSize: 14 }}>{selected.name}</div>
                                        <div style={{ color: '#888', fontSize: 12 }}>{selected.email}</div>
                                    </div>
                                    <button onClick={() => setSelected(null)} style={{ background: 'none', border: 'none', cursor: 'pointer', fontSize: 16, color: '#aaa' }}>✕</button>
                                </div>
                                <StatusBadge status={selected.status} />
                                <table style={{ width: '100%', marginTop: 10, borderCollapse: 'collapse' }}>
                                    <tbody>
                                        {[
                                            ['Role',       (ROLE_STYLE[selected.role] || {}).label || selected.role],
                                            isCentral ? ['Municipality', selected._isResearcher ? 'Central' : munName(selected.municipalityId)] : null,
                                            !selected._isResearcher ? ['Barangay', selected.barangayName || '—'] : null,
                                            !selected._isResearcher ? ['Birthdate', selected.birthdate || '—'] : null,
                                            ['Registered', selected.createdAt ? new Date(selected.createdAt).toLocaleDateString('en-PH', { year: 'numeric', month: 'short', day: 'numeric' }) : '—'],
                                        ].filter(Boolean).map(([label, val]) => (
                                            <tr key={label} style={{ borderBottom: '1px solid #f5f5f5' }}>
                                                <td style={{ padding: '5px 0', color: '#888', width: 90, fontSize: 12 }}>{label}</td>
                                                <td style={{ padding: '5px 0', fontWeight: 500 }}>{val}</td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                                {selected.boat && (
                                    <>
                                        <div style={{ fontWeight: 600, fontSize: 12, marginTop: 12, marginBottom: 6, color: '#333' }}>Boat Details</div>
                                        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                                            <tbody>
                                                {[
                                                    ['Name',   selected.boat.boatName],
                                                    ['Type',   selected.boat.boatType],
                                                    ['Length', selected.boat.length ? `${selected.boat.length} m` : '—'],
                                                    ['Engine', selected.boat.enginePower || '—'],
                                                    ['Reg. #', selected.boat.registrationNumber || '—'],
                                                ].map(([label, val]) => (
                                                    <tr key={label} style={{ borderBottom: '1px solid #f5f5f5' }}>
                                                        <td style={{ padding: '5px 0', color: '#888', width: 90, fontSize: 12 }}>{label}</td>
                                                        <td style={{ padding: '5px 0', fontWeight: 500 }}>{val}</td>
                                                    </tr>
                                                ))}
                                            </tbody>
                                        </table>
                                    </>
                                )}
                                {!isCentral && actionFeedback[selected._id] === 'error' && (
                                    <p style={{ color: '#c00', fontSize: 12, marginTop: 8 }}>Action failed. Try again.</p>
                                )}
                                {!isCentral && selected.role === 'fisher' && (
                                    <div style={{ display: 'flex', gap: 6, marginTop: 12, flexWrap: 'wrap' }}>
                                        <Button variant="success" size="sm" style={{ flex: 1 }}
                                            disabled={selected.status === 'APPROVED' || actionLoading[selected._id]}
                                            onClick={() => handleStatusChange(selected._id, 'APPROVED')}>
                                            {actionLoading[selected._id] ? <Spinner animation="border" size="sm" /> : '✔ Approve'}
                                        </Button>
                                        <Button variant="danger" size="sm" style={{ flex: 1 }}
                                            disabled={selected.status === 'DECLINED' || actionLoading[selected._id]}
                                            onClick={() => handleStatusChange(selected._id, 'DECLINED')}>
                                            {actionLoading[selected._id] ? <Spinner animation="border" size="sm" /> : '✖ Decline'}
                                        </Button>
                                        <Button variant="secondary" size="sm" style={{ flex: 1 }}
                                            disabled={selected.status === 'DEACTIVATED' || actionLoading[selected._id]}
                                            onClick={() => handleStatusChange(selected._id, 'DEACTIVATED')}>
                                            {actionLoading[selected._id] ? <Spinner animation="border" size="sm" /> : '⊘ Deactivate'}
                                        </Button>
                                    </div>
                                )}
                            </div>
                        ) : (
                            <div style={{ background: '#fff', borderRadius: 8, border: '1px dashed #dde3ea', padding: 20, marginBottom: 14, textAlign: 'center', color: '#aaa', fontSize: 13 }}>
                                Click a row to view details
                            </div>
                        )}

                        {/* Distribution chart */}
                        {chartData.length > 1 && (
                            <div style={{ background: '#fff', borderRadius: 8, border: '1px solid #dde3ea', padding: 12 }}>
                                <div style={{ fontSize: 12, fontWeight: 600, color: '#333', marginBottom: 4 }}>
                                    Fisher Distribution — {isCentral && munFilter === 'ALL' ? 'by Municipality' : 'by Barangay'}
                                </div>
                                <Chart
                                    chartType="BarChart"
                                    data={chartData}
                                    width="100%"
                                    height={`${Math.min(220, 40 + (chartData.length - 1) * 24)}px`}
                                    options={{
                                        legend: 'none',
                                        hAxis: { minValue: 0, gridlines: { count: 3 } },
                                        chartArea: { width: '55%', height: '80%' },
                                        bar: { groupWidth: '60%' },
                                        colors: ['#007AFF'],
                                    }}
                                />
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ManageUsers;
